#!/usr/bin/env python3
"""Static self-check for pages generated by the product-design skill.

Standard library only. Usage:
  python3 check_page.py page.html --style business
  python3 check_page.py page.html --case-file evals.json --case-id pricing-business-dark-agency --strict
  python3 check_page.py --selftest
"""
import argparse
import json
import re
import sys
from html.parser import HTMLParser
from pathlib import Path

SKILL_ROOT = Path(__file__).resolve().parent.parent

# Quoted from the style files. `--selftest` fails if any value no longer appears in its file.
STYLE_SPECS = {
    "minimal": {
        "hero_marker": "specimen-field",  # class from the Style Signature hero example
        "file": "shared/visual-style.md",
        "display_font": "DM Sans",
        "accent": ["#141414", "#EDEDED"],
        "button_radius": "2px",
        "grid": "1080px",
        "nav_h": "68px",
        "zero_shadow": True,
    },
    "business": {
        "hero_marker": "biz-stage",  # class from the Style Signature hero example
        "file": "shared/visual-style-business.md",
        "display_font": "Plus Jakarta Sans",
        "accent": ["#071A31", "#F2F4F7"],
        "button_radius": "8px",
        "grid": "1200px",
        "nav_h": "72px",
        "zero_shadow": False,
    },
    "colorful": {
        "hero_marker": "hero-scene",  # class from the Style Signature hero example
        "file": "shared/visual-style-colorful.md",
        "display_font": "Playfair Display",
        "accent": ["#030302", "#F0EDE8"],
        "button_radius": "9999px",
        "grid": "920px",
        "nav_h": "94px",
        "zero_shadow": False,
    },
    "editorial": {
        "hero_marker": "ed-stage",  # class from the Style Signature hero example
        "file": "shared/visual-style-editorial.md",
        "display_font": "Cormorant Garamond",
        "accent": ["#20808D"],
        "button_radius": "9999px",
        "grid": "1440px",
        "nav_h": "64px",
        "zero_shadow": False,
    },
}

# Keep in sync with "Markup conventions" in SKILL.md.
SECTION_VOCAB = {
    "nav", "hero", "page-header", "logo-wall", "problem", "features", "feature-showcase",
    "how-it-works", "use-cases", "integrations", "security", "social-proof", "stats",
    "comparison", "pricing", "billing-toggle", "enterprise", "faq", "cta", "newsletter",
    "story", "team", "values", "timeline", "careers", "contact-form", "contact-info",
    "departments", "featured", "filter", "articles", "pagination", "error", "recovery",
    "platforms", "install", "versions", "footer",
}
SHELL_SECTIONS = {"nav", "footer"}
LOGO_SECTIONS = {"integrations", "logo-wall", "platforms"}
LOGO_SOURCES = ("iconify:", "simple-icons:", "user", "wordmark")
LOGO_HOSTS = ("api.iconify.design", "cdn.simpleicons.org", "cdn.jsdelivr.net/npm/simple-icons")
LAYOUT_TAGS = {"centered-stack", "split-left", "split-right", "bento", "card-grid", "list", "walkthrough",
               "full-bleed", "big-type", "big-quote", "stat-band", "logo-row", "carousel"}
BG_ROLES = {"base", "alt", "dark", "scene"}
SHORT_PAGES = {"pricing", "contact", "404", "downloads"}  # signature-moves.md R4: 0–1 bold sections
STOCK_NAMES = ["Northwind", "Contoso", "Fabrikam", "Globex", "Initech", "Hooli", "Umbrella Corp", "Acme"]
BANNED_PHRASES = ["everything you need", "revolutioniz", "revolutionary", "unlock the power", "unlock your"]
AI_WORDS = ["supercharge", "seamless", "streamline", "empower", "elevate", "effortless", "cutting-edge",
            "next-generation", "next-gen", "unleash", "powerful", "all-in-one"]
SMALL_WORDS = {"a", "an", "and", "as", "at", "but", "by", "for", "in", "of", "on", "or", "the", "to", "with", "vs", "via"}
VOID_TAGS = {"area", "base", "br", "col", "embed", "hr", "img", "input", "link", "meta", "source", "track", "wbr"}
# Text nodes inside these tags are separated by a space; inline tags (span, a, strong…) are not,
# so "<span>$</span>19" reads as "$19".
BLOCK_TAGS = {
    "address", "article", "aside", "blockquote", "br", "button", "dd", "div", "dl", "dt", "fieldset",
    "figcaption", "figure", "footer", "form", "h1", "h2", "h3", "h4", "h5", "h6", "header", "hr",
    "label", "li", "main", "nav", "ol", "option", "p", "pre", "section", "table", "td", "th", "tr", "ul",
}

BTN_SELECTOR = re.compile(r"\.btn(?:-(?:dark|outline|primary|secondary|light|lg|sm))?(?![\w-])")
NAV_SELECTOR = re.compile(r"(^|[\s>+~,(])(nav|header)\b|\.(nav|navbar|site-nav|site-header|header)(?![\w-])")
HEX = re.compile(r"#[0-9a-fA-F]{6}\b|#[0-9a-fA-F]{3}\b")


# ---------------------------------------------------------------- parsing

class PageParser(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.html_attrs = {}
        self.h1 = 0
        self.viewport = False
        self.font_links = []
        self.styles = []
        self.scripts = []
        self.inline_styles = []
        self.sections = []
        self.comments = []
        self.text = []
        self._raw_tag = None
        self._buf = []
        self._stack = []  # (tag, data-section or None, is_sample) for open elements
        self.text_sample = []       # visible text inside data-sample elements
        self.sample_sections = set()  # sections that contain data-sample content
        self.sample_count = 0
        self.section_attrs = []   # attrs of each data-section element, in order
        self.headings = []        # (tag, text) for h1/h2
        self._heading = None
        self.logos = []   # img/svg inside logo sections
        self.hero_classes = set()  # class names used inside the hero section

    def _section(self):
        return next((e[1] for e in reversed(self._stack) if e[1]), None)

    def _in_sample(self):
        return any(e[2] for e in self._stack)

    def handle_starttag(self, tag, attrs):
        a = {k: (v or "") for k, v in attrs}
        section = self._section()
        if tag in ("img", "svg") and section in LOGO_SECTIONS and self._raw_tag is None:
            if not any(e[0] == "svg" for e in self._stack):  # skip <svg> nested in another svg
                self.logos.append({"tag": tag, "section": section, "source": a.get("data-logo-source", ""),
                                   "src": a.get("src", ""), "hidden": a.get("aria-hidden") == "true",
                                   "label": a.get("alt") or a.get("aria-label") or a.get("title") or ""})
        if section == "hero" or a.get("data-section", "").strip() == "hero":
            self.hero_classes.update(a.get("class", "").split())
        is_sample = "data-sample" in a or "data-mock" in a  # mock UI text is illustrative, not a claim
        if "data-sample" in a:
            self.sample_count += 1
            own = a.get("data-section", "").strip()
            for name in ([own] if own else []) + ([section] if section else []):
                self.sample_sections.add(name)
        if tag not in VOID_TAGS:
            self._stack.append((tag, a.get("data-section", "").strip() or None, is_sample))
        if tag in BLOCK_TAGS:
            self.text.append(" ")
            if self._heading:
                self._heading[1].append(" ")
        if tag == "html":
            self.html_attrs = a
        elif tag == "h1":
            self.h1 += 1
        elif tag == "meta" and a.get("name", "").lower() == "viewport":
            self.viewport = True
        elif tag == "link" and "fonts.googleapis.com" in a.get("href", ""):
            self.font_links.append(a["href"])
        if a.get("data-section"):
            self.sections.append(a["data-section"].strip())
            self.section_attrs.append(a)
        if tag in ("h1", "h2"):
            self._heading = [tag, []]
        if a.get("style"):
            self.inline_styles.append(a["style"])
        if tag in ("script", "style"):
            self._raw_tag = tag
            self._buf = []

    def handle_endtag(self, tag):
        if self._heading and tag == self._heading[0]:
            self.headings.append((tag, norm("".join(self._heading[1]))))
            self._heading = None
        for i in range(len(self._stack) - 1, -1, -1):
            if self._stack[i][0] == tag:
                del self._stack[i:]
                break
        if tag in BLOCK_TAGS:
            self.text.append(" ")
        if tag == self._raw_tag:
            content = "".join(self._buf)
            (self.styles if tag == "style" else self.scripts).append(content)
            self._raw_tag = None

    def handle_data(self, data):
        if self._heading and not self._raw_tag:
            self._heading[1].append(data)
        if self._raw_tag:
            self._buf.append(data)
        elif self._in_sample():
            self.text_sample.append(data)
            self.text.append(" ")
        else:
            self.text.append(data)

    def handle_comment(self, data):
        self.comments.append(data)


def parse_css(css):
    """Return rules as dicts: selector, decls [(prop, value)], context [at-rule preludes]."""
    css = re.sub(r"/\*.*?\*/", "", css, flags=re.S)
    rules = []

    def block(i, context):
        buf = []
        n = len(css)
        while i < n:
            c = css[i]
            if c == "{":
                prelude = "".join(buf).strip()
                buf = []
                if prelude.startswith("@") and "keyframes" in prelude.split()[0]:
                    depth, i = 1, i + 1
                    while i < n and depth:
                        depth += (css[i] == "{") - (css[i] == "}")
                        i += 1
                    rules.append({"selector": prelude, "decls": [], "context": context, "keyframes": True})
                    continue
                if prelude.startswith("@media") or prelude.startswith("@supports") or prelude.startswith("@layer") or prelude.startswith("@container"):
                    i = block(i + 1, context + [prelude])
                    continue
                end = css.find("}", i + 1)
                end = n if end == -1 else end
                decls = []
                for d in css[i + 1:end].split(";"):
                    if ":" in d:
                        p, v = d.split(":", 1)
                        decls.append((p.strip().lower(), v.strip()))
                rules.append({"selector": prelude, "decls": decls, "context": context})
                i = end + 1
                continue
            if c == "}":
                return i + 1
            buf.append(c)
            i += 1
        return i

    block(0, [])
    return rules


def norm(s):
    return re.sub(r"\s+", " ", s).strip()


def px(value):
    m = re.search(r"(-?\d+(?:\.\d+)?)px", value)
    return float(m.group(1)) if m else None


def norm_hex(h):
    h = h.upper()
    if len(h) == 4:
        h = "#" + "".join(ch * 2 for ch in h[1:])
    return h


# ---------------------------------------------------------------- checks

class Report:
    def __init__(self):
        self.errors, self.warnings, self.passed = [], [], []

    def check(self, ok, rule, msg, level="error"):
        if ok:
            self.passed.append(rule)
        elif level == "error":
            self.errors.append((rule, msg))
        else:
            self.warnings.append((rule, msg))


def run_checks(path, style=None, case=None, strict=False):
    html = Path(path).read_text(encoding="utf-8", errors="replace")
    p = PageParser()
    p.feed(html)
    css_text = "\n".join(p.styles)
    rules = parse_css(css_text) + [{"selector": "[style]", "decls": parse_css("x{" + s + "}")[0]["decls"], "context": []} for s in p.inline_styles]
    js = "\n".join(p.scripts)
    visible = norm("".join(p.text))  # real content only; data-sample text is excluded
    full_text = norm(visible + " " + " ".join(p.text_sample))
    r = Report()
    case_checks = (case or {}).get("checks", {})
    style = style or case_checks.get("style") or p.html_attrs.get("data-style")
    style_level = "error" if strict else "warn"

    decls = [(rule["selector"], prop, val, rule["context"]) for rule in rules for prop, val in rule["decls"]]

    # Structure and conventions
    r.check(p.h1 == 1, "structure.single-h1", f"expected exactly one <h1>, found {p.h1}")
    r.check(p.viewport, "structure.viewport", "missing <meta name=\"viewport\">")
    r.check(bool(p.html_attrs.get("lang")), "structure.lang", "<html> has no lang attribute", "warn")
    for attr in ("data-page", "data-style", "data-theme"):
        r.check(bool(p.html_attrs.get(attr)), f"convention.{attr}", f"<html> is missing {attr} (see Markup conventions in SKILL.md)", "warn")
    r.check(bool(p.sections), "convention.data-section", "no data-section markers; structure checks skipped", "warn")
    unknown = sorted({s for s in p.sections if s not in SECTION_VOCAB})
    r.check(not unknown, "convention.section-names", f"data-section names outside the vocabulary: {', '.join(unknown)}", style_level)

    # Rhythm (shared/signature-moves.md §2)
    content = [a for a in p.section_attrs if a.get("data-section") not in SHELL_SECTIONS]
    if len(content) >= 2:
        missing = [a.get("data-section") for a in content if not a.get("data-layout") or not a.get("data-bg")]
        r.check(not missing, "rhythm.markup", f"sections without data-layout/data-bg: {', '.join(missing[:6])}", style_level)
        bad_tags = sorted({a.get("data-layout") for a in content if a.get("data-layout") and a.get("data-layout") not in LAYOUT_TAGS})
        r.check(not bad_tags, "rhythm.layout-tags", f"unknown data-layout tags: {', '.join(bad_tags)}", style_level)
        bad_bgs = sorted({a.get("data-bg") for a in content if a.get("data-bg") and a.get("data-bg") not in BG_ROLES})
        r.check(not bad_bgs, "rhythm.bg-roles", f"unknown data-bg roles: {', '.join(bad_bgs)}", style_level)
        layouts = [a.get("data-layout") for a in content]
        repeats = [f"{content[i].get('data-section')}→{content[i+1].get('data-section')} ({layouts[i]})"
                   for i in range(len(layouts) - 1) if layouts[i] and layouts[i] == layouts[i + 1]]
        r.check(not repeats, "rhythm.adjacent-layout", f"adjacent sections share a layout: {'; '.join(repeats[:4])}", style_level)
        bgs = [a.get("data-bg") for a in content]
        if all(bgs):
            changes = sum(1 for i in range(len(bgs) - 1) if bgs[i] != bgs[i + 1])
            need = (len(bgs) - 1) // 2
            r.check(changes >= need, "rhythm.background-changes", f"background changes at {changes} of {len(bgs)-1} boundaries; want at least {need}", "warn")
        bold = sum(1 for a in content if a.get("data-bold") == "true")
        short_page = p.html_attrs.get("data-page") in SHORT_PAGES
        lo, hi = (0, 1) if short_page else (1, 2)
        r.check(lo <= bold <= hi, "rhythm.bold-count", f"{bold} bold content sections; want {lo}–{hi} (hero included; the M14 wordmark footer is not counted)", "warn")
        grids = sum(1 for l in layouts if l == "card-grid")
        r.check(grids <= 1, "rhythm.card-grids", f"{grids} equal-card grids; at most 1 per page", "warn")

    # Copy (shared/copy.md)
    for tag, text in p.headings:
        low = text.lower()
        words = [w for w in re.findall(r"[A-Za-z][A-Za-z'’-]*", text)]
        hits = [b for b in BANNED_PHRASES if b in low]
        r.check(not hits, "copy.banned-phrase", f"{tag} uses a banned phrase ({', '.join(hits)}): {text!r}", "warn")
        caps = [w for w in words if w.lower() not in SMALL_WORDS]
        title_case = len(caps) >= 3 and all(w[0].isupper() for w in caps) and not text.isupper()
        r.check(not title_case, "copy.sentence-case", f"{tag} in Title Case; use sentence case: {text!r}", "warn")
        if p.html_attrs.get("data-page") != "contact":  # contact headers may be questions (shared/copy.md §1)
            r.check(not text.rstrip().endswith("?"), "copy.no-question-headline", f"{tag} written as a question: {text!r}", "warn")
        ai = sorted({w for w in AI_WORDS if re.search(r"\b" + re.escape(w), low)} - ({"next-gen"} if "next-generation" in low else set()))
        r.check(len(ai) <= 1, "copy.ai-words", f"{tag} uses {len(ai)} AI words ({', '.join(ai)}): {text!r}", "warn")
        if tag == "h1":
            r.check(len(words) <= 8, "copy.hero-length", f"hero headline has {len(words)} words; aim for 4–8: {text!r}", "warn")

    # Stock placeholder names and bracket placeholders read as fake at a glance (master SKILL.md, Sample content)
    stock = sorted({n for n in STOCK_NAMES if re.search(r"\b" + n + r"\b", full_text)})
    r.check(not stock, "copy.stock-names", f"stock placeholder company names ({', '.join(stock)}); invent names per page", "warn")
    brackets = sorted(set(re.findall(r"\[[A-Z][A-Za-z ]{2,40}\]", full_text)) - {"[Product]"})
    r.check(not brackets, "copy.bracket-placeholder", f"bracket placeholders on the page: {', '.join(brackets[:5])}", "warn")

    # Logos: every logo states its source; drawn logos are the most visible AI tell
    if p.logos:
        logos = [l for l in p.logos if not l["hidden"]]
        unmarked = [l for l in logos if not l["source"]]
        r.check(not unmarked, "logos.source-marked",
                f"{len(unmarked)} logo image(s) in {', '.join(sorted({l['section'] for l in unmarked}))} have no data-logo-source; "
                "take logos from Iconify / Simple Icons or use a wordmark, never draw them", style_level)
        bad = [l["source"] for l in logos if l["source"] and not l["source"].startswith(LOGO_SOURCES)]
        r.check(not bad, "logos.source-valid", f"unknown data-logo-source values: {', '.join(bad[:5])}", style_level)
        offhost = [l["src"] for l in logos if l["tag"] == "img" and l["src"].startswith("http")
                   and l["source"] != "user" and not any(h in l["src"] for h in LOGO_HOSTS)]
        r.check(not offhost, "logos.source-host", f"logo images from unknown hosts: {', '.join(offhost[:3])}", style_level)

    # CSS correctness
    defined = set(re.findall(r"(--[\w-]+)\s*:", css_text + "\n" + "\n".join(p.inline_styles)))
    defined |= set(re.findall(r"setProperty\(\s*['\"](--[\w-]+)", js))
    used_no_fallback = set(re.findall(r"var\(\s*(--[\w-]+)\s*\)", css_text + "\n" + "\n".join(p.inline_styles) + "\n" + js))
    undefined = sorted(used_no_fallback - defined)
    r.check(not undefined, "css.undefined-vars", f"var() used but never defined: {', '.join(undefined)}")

    vw = [s for s, prop, val, _ in decls if prop in ("width", "min-width") and "100vw" in val]
    r.check(not vw, "css.no-100vw", f"width: 100vw causes horizontal scroll; use 100%: {', '.join(vw[:5])}")

    stripes = []
    for s, prop, val, _ in decls:
        if prop in ("border-left", "border-inline-start", "border-left-width", "border-inline-start-width"):
            w = px(val)
            if w is not None and w >= 2 and "none" not in val and "transparent" not in val:  # transparent = CSS triangle trick
                stripes.append(f"{norm(s)} {{{prop}: {val}}}")
    r.check(not stripes, "design.no-left-border-accent", f"left-edge stripe found (reads as AI-generated): {'; '.join(stripes[:3])}")

    fixed_nav = [s for s, prop, val, _ in decls if prop == "position" and val in ("fixed", "sticky") and NAV_SELECTOR.search(s)]
    if fixed_nav:
        blurred = any(prop in ("backdrop-filter", "-webkit-backdrop-filter") and "blur" in val and NAV_SELECTOR.search(s) for s, prop, val, _ in decls)
        r.check(blurred, "design.nav-backdrop-blur", "fixed nav has no backdrop-filter: blur(...)")

    # Motion safety
    anim = [(s, ctx) for s, prop, val, ctx in decls if prop in ("animation", "animation-name") and val.lower() not in ("none", "initial", "unset")]
    has_motion = bool(anim) or any(rule.get("keyframes") for rule in rules) or bool(re.search(r"IntersectionObserver|requestAnimationFrame|\.animate\(", js))
    if has_motion:
        r.check("prefers-reduced-motion" in css_text + js, "motion.reduced-motion", "page animates but never checks prefers-reduced-motion")
        loose = [norm(s) for s, ctx in anim if not any("prefers-reduced-motion" in c and "no-preference" in c for c in ctx)]
        r.check(not loose, "motion.animation-guarded", f"animation declared outside @media (prefers-reduced-motion: no-preference): {', '.join(loose[:4])}", "warn")

    # Accessibility and responsiveness
    r.check(":focus-visible" in css_text, "a11y.focus-visible", "no :focus-visible style", "warn")
    contexts = {norm(c) for rule in rules for c in rule["context"]}
    r.check(any("max-width" in c for c in contexts), "responsive.media-query", "no max-width media query for narrow screens", "warn")
    r.check(not any(re.search(r"max-width:\s*768px", c) for c in contexts), "responsive.breakpoint-767", "uses max-width: 768px; the system breakpoint is 767px", "warn")

    # Style fidelity
    spec = STYLE_SPECS.get(style) if style else None
    if not spec:
        r.check(False, "style.known", f"style unknown ({style!r}); style checks skipped", "warn")
    else:
        font = case_checks.get("display_font") or spec["display_font"]
        font_vals = [val for s, prop, val, _ in decls if prop == "--font-display"]
        if font_vals:
            r.check(any(font.lower() in v.lower() for v in font_vals), "style.display-font", f"--font-display should use {font!r}, found {font_vals[0]!r}", "error" if case_checks.get("display_font") else style_level)
        else:
            r.check(False, "style.display-font", "no --font-display custom property", "warn")
        r.check(any(font.replace(" ", "+") in link for link in p.font_links), "style.fonts-link", f"no Google Fonts link loading {font!r}", "warn")

        accents = [norm_hex(m) for s, prop, val, _ in decls if prop == "--accent" for m in HEX.findall(val)]
        expected = [norm_hex(case_checks["accent"])] if case_checks.get("accent") else [norm_hex(a) for a in spec["accent"]]
        r.check(any(a in expected for a in accents), "style.accent", f"--accent should be one of {expected}, found {sorted(set(accents)) or 'none'}", "error" if case_checks.get("accent") else style_level)

        props = {prop: val.strip() for s, prop, val, _ in decls if prop.startswith("--")}
        def resolve(v, depth=0):  # follow var(--x) to its custom property value
            m = re.fullmatch(r"var\((--[\w-]+)(?:,\s*([^)]+))?\)", v.strip())
            if not m or depth > 5:
                return v
            return resolve(props.get(m.group(1), m.group(2) or v), depth + 1)
        radii = [(norm(s), resolve(val)) for s, prop, val, _ in decls if prop == "border-radius" and BTN_SELECTOR.search(s)]
        if radii:
            want = spec["button_radius"]
            if want == "9999px":
                bad = [f"{s}: {v}" for s, v in radii if (px(v) or 0) < 999]
            else:
                bad = [f"{s}: {v}" for s, v in radii if v.split()[0] != want]
            r.check(not bad, "style.button-radius", f"button radius should be {want}: {'; '.join(bad[:3])}", style_level)
        else:
            r.check(False, "style.button-radius", "no .btn rules with border-radius found", "warn")

        if spec["zero_shadow"]:
            shadows = [norm(s) for s, prop, val, _ in decls if prop == "box-shadow" and val.strip().lower() not in ("none", "0", "inherit", "initial", "unset")]
            r.check(not shadows, "style.zero-shadow", f"Minimal uses zero shadows; box-shadow on: {', '.join(shadows[:4])}", style_level)

        r.check(re.search(r"max-width:\s*" + re.escape(spec["grid"]), css_text) is not None, "style.grid", f"main grid max-width {spec['grid']} not found", "warn")
        navh = [val for s, prop, val, _ in decls if prop == "--nav-h"]
        if "nav" in p.sections or navh:
            r.check(spec["nav_h"] in navh, "style.nav-height", f"--nav-h should be {spec['nav_h']}, found {navh or 'none'}", "warn")

        if "hero" in p.sections:
            marker = spec["hero_marker"]
            r.check(marker in p.hero_classes, "style.signature-hero", f"hero does not use the {style} Hero showcase (no .{marker}); build it from the Style Signature example unless the user asked for another hero", "warn")

        style_file = SKILL_ROOT / spec["file"]
        palette = {norm_hex(h) for h in HEX.findall(style_file.read_text())} if style_file.exists() else set()
        pv = SKILL_ROOT / "shared" / "product-visuals.md"
        if pv.exists():  # mock UI status colors are allowed inside data-mock frames
            palette |= {norm_hex(h) for h in HEX.findall(pv.read_text())}
        palette |= {"#FFFFFF", "#000000"} | set(expected)
        used = [norm_hex(h) for s, prop, val, _ in decls if not prop.startswith("--font") for h in HEX.findall(val)]
        foreign = sorted({h for h in used if h not in palette})
        r.check(not foreign, "style.palette", f"colors not in the {style} style file (fine inside product mocks, otherwise suspicious): {', '.join(foreign[:10])}", "warn")

    # Case expectations
    if case_checks:
        attrs = p.html_attrs
        for key in ("page", "style", "theme"):
            if case_checks.get(key):
                r.check(attrs.get(f"data-{key}") == case_checks[key], f"case.{key}", f"data-{key} is {attrs.get(f'data-{key}')!r}, expected {case_checks[key]!r}")
        if case_checks.get("archetype"):
            r.check(attrs.get("data-archetype") in case_checks["archetype"], "case.archetype", f"data-archetype is {attrs.get('data-archetype')!r}, expected one of {case_checks['archetype']}")
        present = set(p.sections)
        for s in case_checks.get("sections_required", []):
            r.check(s in present, f"case.has-{s}", f"required section {s!r} missing")
        for s in case_checks.get("sections_forbidden", []):
            r.check(s not in present, f"case.no-{s}", f"section {s!r} should not be on this page (the user said they don't have it)")
        for s in case_checks.get("sections_must_be_sample", []):
            if s in present:
                r.check(s in p.sample_sections, f"case.sample-{s}", f"section {s!r} shows material the user never gave but is not marked data-sample")
        for s in case_checks.get("sections_recommended", []):
            r.check(s in present, f"case.recommended-{s}", f"recommended section {s!r} missing", "warn")
        for group in case_checks.get("sections_any_of", []):
            r.check(bool(present & set(group)), "case.any-of-" + "-".join(group), f"expected one of {group}")
        if "max_content_sections" in case_checks:
            content = [s for s in p.sections if s not in SHELL_SECTIONS]
            r.check(len(content) <= case_checks["max_content_sections"], "case.max-sections", f"{len(content)} content sections, expected at most {case_checks['max_content_sections']}: {', '.join(content)}")
        low = visible.lower()
        full_low = full_text.lower()
        squashed = re.sub(r"\s+", "", full_low)  # "$ 19" from <span>$</span> <span>19</span> still matches "$19"
        for t in case_checks.get("text_required", []):
            r.check(t.lower() in full_low or re.sub(r"\s+", "", t.lower()) in squashed, "case.text-required", f"missing text {t!r}")
        for t in case_checks.get("text_forbidden", []):
            r.check(t.lower() not in low, "case.text-forbidden", f"should not contain {t!r}")
        for rx in case_checks.get("regex_required", []):
            r.check(re.search(rx, full_text) is not None, "case.regex-required", f"no match for /{rx}/")
        for rx in case_checks.get("regex_forbidden", []):
            m = re.search(rx, visible)
            r.check(m is None, "case.regex-forbidden", f"unexpected match for /{rx}/: {m.group(0) if m else ''!r}")

    info = {
        "sections": p.sections,
        "placeholders": len(re.findall(r"\[[^\[\]]{2,60}\]", visible)),
        "logos": len(p.logos),
        "sample_elements": p.sample_count,
        "sample_sections": sorted(p.sample_sections),
        "invented_markers": sum("INVENTED" in c for c in p.comments) + css_text.count("INVENTED"),
        "style": style,
    }
    return r, info


def selftest():
    failures = []
    for name, spec in STYLE_SPECS.items():
        text = (SKILL_ROOT / spec["file"]).read_text()
        for key in ("display_font", "button_radius", "grid", "nav_h", "hero_marker"):
            if spec[key] not in text:
                failures.append(f"{name}: {key} {spec[key]!r} not found in {spec['file']}")
        for a in spec["accent"]:
            if a.lower() not in text.lower():
                failures.append(f"{name}: accent {a} not found in {spec['file']}")
    skill_md = (SKILL_ROOT / "SKILL.md").read_text()
    missing = [s for s in SECTION_VOCAB if f"`{s}`" not in skill_md]
    if missing:
        failures.append(f"section names not listed in SKILL.md: {', '.join(sorted(missing))}")
    for f in failures:
        print("FAIL", f)
    print("selftest:", "ok" if not failures else f"{len(failures)} failure(s)")
    return 1 if failures else 0


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("page", nargs="?")
    ap.add_argument("--style", choices=sorted(STYLE_SPECS))
    ap.add_argument("--case-file")
    ap.add_argument("--case-id")
    ap.add_argument("--strict", action="store_true", help="treat style deviations as errors (evals)")
    ap.add_argument("--json", help="also write the report as JSON to this path")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args()

    if args.selftest:
        sys.exit(selftest())
    if not args.page:
        ap.error("page is required")

    case = None
    if args.case_file and args.case_id:
        cases = json.loads(Path(args.case_file).read_text())["evals"]
        case = next((c for c in cases if c.get("name") == args.case_id or str(c.get("id")) == args.case_id), None)
        if case is None:
            ap.error(f"case {args.case_id!r} not found")

    r, info = run_checks(args.page, args.style, case, args.strict)
    for rule, msg in r.errors:
        print(f"ERROR  {rule}: {msg}")
    for rule, msg in r.warnings:
        print(f"WARN   {rule}: {msg}")
    print(f"\n{len(r.passed)} passed · {len(r.errors)} errors · {len(r.warnings)} warnings")
    print(f"style: {info['style']} · sections: {', '.join(info['sections']) or '(none marked)'}")
    print(f"placeholders: {info['placeholders']} · sample elements: {info['sample_elements']} · INVENTED markers: {info['invented_markers']}")

    if args.json:
        Path(args.json).write_text(json.dumps({
            "page": str(args.page),
            "case": case.get("name") if case else None,
            "passed": not r.errors,
            "errors": [{"rule": a, "message": b} for a, b in r.errors],
            "warnings": [{"rule": a, "message": b} for a, b in r.warnings],
            "passed_checks": r.passed,
            "info": info,
        }, indent=2))
    sys.exit(1 if r.errors else 0)


if __name__ == "__main__":
    main()
